1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>A 2-CTA Cluster</title>
7	<link rel="stylesheet" href="../viz-base.css">
8	<script src="../viz-base.js"></script>
9	<style>
10	  body { padding: 16px 28px; max-width: 980px; margin: 0 auto; }
11	  h1 { font-size: 26px; line-height: 1.1; margin-bottom: 6px; }
12	
13	  /* outer cluster box */
14	  .cluster { border: 2.5px dashed #94a3b8; background: #f8fafc; border-radius: 12px;
15	             position: relative; padding: 28px 16px 16px; max-width: 860px; margin: 0 auto; cursor: pointer; }
16	  .ctag { position: absolute; top: -11px; left: 16px; background: #64748b; color: #fff;
17	          font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 4px; letter-spacing: .02em; }
18	
19	  .grid3 { display: grid; grid-template-columns: 1fr auto 1fr; gap: 12px; align-items: center; }
20	
21	  .cta { border: 2.5px solid; border-radius: 10px; padding: 10px; display: flex; flex-direction: column; gap: 8px; }
22	  .cta0 { border-color: #94a3b8; background: #fff; }
23	  .cta1 { border-color: #94a3b8; background: #fff; border-style: dashed; }
24	  .hd { font-size: 14px; font-weight: 700; text-align: center; }
25	  .cta0 .hd, .cta1 .hd { color: #334155; }
26	
27	  .slot { border: 2px solid; border-radius: 8px; padding: 8px 6px; text-align: center; cursor: pointer;
28	          transition: box-shadow .15s; }
29	  .slot b { display: block; font-size: 13px; }
30	  .slot span { font-size: 11.5px; color: #475569; }
31	  .asmem { background: #ede9fe; border-color: #8b5cf6; }
32	  .bsmem { background: #ddd6fe; border-color: #6d28d9; }
33	  .out   { background: #fffbeb; border-color: #f59e0b; }
34	
35	  .mid { display: flex; align-items: center; justify-content: center; }
36	  .xread { background: #dcfce7; border: 2.2px solid #059669; color: #047857; font-weight: 700;
37	           font-size: 12.5px; line-height: 1.25; text-align: center; border-radius: 9px;
38	           padding: 8px 10px; cursor: pointer; white-space: nowrap; transition: box-shadow .15s; }
39	
40	  .summary { margin-top: 12px; background: #fffbeb; border: 2px solid #f59e0b; border-radius: 9px;
41	             padding: 8px 12px; text-align: center; font-size: 13px; font-weight: 700; color: #c2410c; }
42	
43	  .sel { box-shadow: 0 0 0 3px rgba(0,0,0,.18); }
44	
45	  .detail-panel { max-width: 860px; margin: 14px auto 0; border: 1px solid var(--border);
46	    border-radius: 10px; background: var(--surface); padding: 10px 16px; min-height: 84px; }
47	  .dp-title { font-size: 12.5px; font-weight: 700; margin-bottom: 4px; }
48	  .dp-body  { font-size: 12px; line-height: 1.6; color: #475569; }
49	  .dp-body code { font-family: 'SF Mono','Fira Code',monospace; font-size: 11px; background: #f1f5f9;
50	    padding: 1px 5px; border-radius: 3px; color: #1e293b; }
51	
52	  @media (max-width: 640px) { .grid3 { grid-template-columns: 1fr; } .mid { transform: rotate(90deg); } }
53	</style>
54	</head>
55	<body>
56	<h1>A 2-CTA Cluster: Cooperative MMA via Cross-CTA SMEM Read</h1>
57	<div class="sub">click a piece — two CTAs share stored-B row slices across the cluster (DSMEM)</div>
58	
59	<div class="cluster" id="diagram" data-k="cluster">
60	  <span class="ctag">CLUSTER — 2 CTAs across SMs · DSMEM</span>
61	  <div class="grid3">
62	    <div class="cta cta0" data-k="cta">
63	      <div class="hd">CTA 0 · SM-0</div>
64	      <div class="slot asmem" data-k="asmem"><b>Asmem (own)</b><span>A rows 0–127</span></div>
65	      <div class="slot bsmem" data-k="bsmem"><b>Bsmem</b><span>B stored rows 0–127</span></div>
66	      <div class="slot out"   data-k="out"><b>D[0:128, 0:256]</b></div>
67	    </div>
68	    <div class="mid">
69	      <div class="xread" data-k="xread">cross-CTA<br>read&nbsp;↔</div>
70	    </div>
71	    <div class="cta cta1" data-k="cta">
72	      <div class="hd">CTA 1 · SM-1</div>
73	      <div class="slot asmem" data-k="asmem"><b>Asmem (own)</b><span>A rows 128–255</span></div>
74	      <div class="slot bsmem" data-k="bsmem"><b>Bsmem</b><span>B stored rows 128–255</span></div>
75	      <div class="slot out"   data-k="out"><b>D[128:256, 0:256]</b></div>
76	    </div>
77	  </div>
78	  <div class="summary">Cluster output: 256 × 256 — twice the 128 × 128 one CTA computes alone</div>
79	</div>
80	
81	<div class="detail-panel" id="detail">
82	  <div class="dp-title" id="dpt"></div>
83	  <div class="dp-body" id="dpb"></div>
84	</div>
85	
86	<script>
87	(function () {
88	  var INFO = {
89	    cluster: ["Cluster — 2 CTAs across SMs", "A cluster groups CTAs on different SMs so they can synchronize and read each other's shared memory directly (<b>DSMEM</b>). Here a 2-CTA cluster computes one 256&times;256 output tile cooperatively."],
90	    cta:     ["CTA — one thread block on one SM", "Each CTA runs on a single SM and owns that SM's shared memory. On its own it would compute a 128&times;256 slice of the output; in the cluster the two CTAs combine into a larger MMA."],
91	    asmem:   ["Asmem (own) — this CTA's A row slice", "Each CTA stages its own rows of A in shared memory: CTA 0 holds <code>A rows 0&ndash;127</code>, CTA 1 holds <code>A rows 128&ndash;255</code>."],
92	    bsmem:   ["Bsmem — this CTA's stored-B row slice", "Each CTA stages one stored-B row slice (CTA 0: <code>rows 0&ndash;127</code>; CTA 1: <code>rows 128&ndash;255</code>). After <code>B.T</code>, those slices become logical output-column spans. The MMA needs both spans, so each CTA also reads the <em>other</em> CTA's Bsmem across the cluster."],
93	    xread:   ["Cross-CTA read (DSMEM)", "A CTA reads the other CTA's stored-B slice from <code>Bsmem</code> directly over the cluster interconnect &mdash; no round-trip through global memory. This distributed-shared-memory access is what makes the 2-CTA cooperative MMA possible."],
94	    out:     ["Output — a 256&times;256 tile", "Together the pair produces a 256&times;256 tile (CTA 0: rows 0&ndash;127, CTA 1: rows 128&ndash;255), twice the 128&times;128 a single CTA would produce alone."]
95	  };
96	  var diagram = document.getElementById('diagram');
97	  var dpt = document.getElementById('dpt'), dpb = document.getElementById('dpb');
98	
99	  function select(k) {
100	    diagram.parentNode.querySelectorAll('.sel').forEach(function (e) { e.classList.remove('sel'); });
101	    diagram.querySelectorAll('[data-k="' + k + '"]').forEach(function (e) { e.classList.add('sel'); });
102	    dpt.innerHTML = INFO[k][0];
103	    dpb.innerHTML = INFO[k][1];
104	  }
105	  diagram.addEventListener('click', function (e) {
106	    var el = e.target.closest('[data-k]');
107	    if (el) select(el.dataset.k);
108	  });
109	  select('xread');   // default: the cross-CTA read is the point of the figure
110	})();
111	</script>
112	</body>
113	</html>
